if (phoneContent) { phoneContent.innerHTML = screens.home; document.querySelectorAll('[data-screen]').forEach(button => button.addEventListener('click', () => { document.querySelectorAll('[data-screen]').forEach(b => { b.classList.toggle('selected', b === button); b.setAttribute('aria-pressed', String(b === button)); }); phoneContent.innerHTML = screens[button.dataset.screen]; })); }
